//	    email = COALESCE($6, email),
//	    password_hash = COALESCE($7, password_hash),
//	    user_type = COALESCE($8, user_type),
//	    is_active = COALESCE($9, is_active),
//	    settings = COALESCE($10, settings),
//	    updated_at = NOW()
//	WHERE id = $1 AND tenant_id = current_tenant_id() AND deleted_at IS NULL
//	RETURNING id, tenant_id, entity_id, person_id, employee_id, username, email, password_hash, user_type, is_active, last_login_at, password_changed_at, settings, created_at, updated_at, deleted_at
func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (*User, error) {
	row := q.db.QueryRow(ctx, updateUser,
		arg.ID,
		arg.EntityID,
		arg.PersonID,
		arg.EmployeeID,
		arg.Username,
		arg.Email,
		arg.PasswordHash,
		arg.UserType,
		arg.IsActive,
		arg.Settings,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.EntityID,
		&i.PersonID,
		&i.EmployeeID,
		&i.Username,
		&i.Email,
		&i.PasswordHash,
		&i.UserType,
		&i.IsActive,
		&i.LastLoginAt,
		&i.PasswordChangedAt,
		&i.Settings,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return &i, err
}

